{
  "name": "SHFQC量子控制器",
  "name_en": "SHFQC Quantum Controller",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台面向量子计算实验的高频量子控制与读出仪器，集成信号发生、AWG/序列器、触发、波形存储、积分权重、读出和结果记录等功能，可用于量子比特或量子多能级态实验中的微波脉冲生成、序列控制与测量读出。",
  "description_en": "This is a high-frequency quantum control and readout instrument for quantum computing experiments. It integrates signal generation, AWG/sequencer control, triggering, waveform memory, integration weights, readout, and result logging for microwave pulse generation, sequence control, and measurement readout of qubits or qudits.",
  "tag_hints": [
    "quantum control",
    "qubit readout",
    "microwave signal generation",
    "AWG sequencer",
    "software triggering",
    "integration weights",
    "qudit measurement"
  ],
  "actions": [
    {
      "action_name": "auto-factory_reset",
      "description": "恢复出厂默认设置。",
      "description_en": "Restore the factory default settings."
    },
    {
      "action_name": "auto-start_continuous_sw_trigger",
      "description": "按设定次数和间隔发送连续软件触发。",
      "description_en": "Issue continuous software triggers with the specified count and interval."
    },
    {
      "action_name": "auto-check_status",
      "description": "检查当前操作或模块状态。",
      "description_en": "Check the current operation or module status."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "加载命令表的验证模式。",
      "description_en": "Load the validation schema for the command table."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表上传到设备。",
      "description_en": "Upload the command table to the device."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从设备读取命令表。",
      "description_en": "Load the command table from the device."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用序列器。",
      "description_en": "Enable the sequencer."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待当前操作完成。",
      "description_en": "Wait until the current operation is done."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译seqC序列程序。",
      "description_en": "Compile the seqC sequencer program."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将序列程序加载到设备。",
      "description_en": "Load the sequencer program onto the device."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "将波形写入波形存储器。",
      "description_en": "Write waveforms to waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从波形存储器读取波形。",
      "description_en": "Read waveforms from waveform memory."
    },
    {
      "action_name": "auto-configure_marker_and_trigger",
      "description": "配置标记与触发设置。",
      "description_en": "Configure marker and trigger settings."
    },
    {
      "action_name": "auto-available_trigger_inputs",
      "description": "获取可用触发输入列表。",
      "description_en": "Get the available trigger inputs."
    },
    {
      "action_name": "auto-available_trigger_slopes",
      "description": "获取可用触发沿类型。",
      "description_en": "Get the available trigger slopes."
    },
    {
      "action_name": "auto-available_marker_outputs",
      "description": "获取可用标记输出列表。",
      "description_en": "Get the available marker outputs."
    },
    {
      "action_name": "auto-configure_channel",
      "description": "配置通道参数。",
      "description_en": "Configure channel parameters."
    },
    {
      "action_name": "auto-configure_pulse_modulation",
      "description": "配置脉冲调制。",
      "description_en": "Configure pulse modulation."
    },
    {
      "action_name": "auto-configure_sine_generation",
      "description": "配置正弦信号生成。",
      "description_en": "Configure sine generation."
    },
    {
      "action_name": "auto-awg_modulation_freq",
      "description": "获取或设置AWG调制频率。",
      "description_en": "Get or set the AWG modulation frequency."
    },
    {
      "action_name": "auto-configure_sequencer_triggering",
      "description": "配置序列器触发方式。",
      "description_en": "Configure sequencer triggering."
    },
    {
      "action_name": "auto-available_aux_trigger_inputs",
      "description": "获取可用辅助触发输入列表。",
      "description_en": "Get the available auxiliary trigger inputs."
    },
    {
      "action_name": "auto-configure",
      "description": "应用基本配置。",
      "description_en": "Apply the basic configuration."
    },
    {
      "action_name": "auto-get_qudits_results",
      "description": "获取量子多能级态读出结果。",
      "description_en": "Get qudit readout results."
    },
    {
      "action_name": "auto-configure_result_logger",
      "description": "配置结果记录器。",
      "description_en": "Configure the result logger."
    },
    {
      "action_name": "auto-read",
      "description": "读取采集或结果数据。",
      "description_en": "Read acquired or result data."
    },
    {
      "action_name": "auto-write_integration_weights",
      "description": "写入积分权重。",
      "description_en": "Write integration weights."
    },
    {
      "action_name": "auto-read_integration_weights",
      "description": "读取积分权重。",
      "description_en": "Read integration weights."
    },
    {
      "action_name": "auto-available_inputs",
      "description": "获取可用输入列表。",
      "description_en": "Get the available inputs."
    },
    {
      "action_name": "auto-max_qubits_per_channel",
      "description": "获取每通道支持的最大量子比特数。",
      "description_en": "get maximum number of supported qubits per channel"
    }
  ]
}

